// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address a, address b) internal {
        bool firstOk;
        bool secondOk;
        try c.setOwner(a) returns (bool r1) {
            firstOk = r1;
        } catch {
            firstOk = false;
        }
        try c.setOwner(b) returns (bool r2) {
            secondOk = r2;
        } catch {
            secondOk = false;
        }
        assertTrue(!firstOk || !secondOk || c.owner() == b);
    }

    function testFuzz_run(address a, address b) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(b.code.length == 0 && uint160(b) > 0xffff && b != address(this) && b != address(c) && b != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && b != 0x000000000000000000636F6e736F6c652e6c6f67 && b != 0x4e59b44847b379578588920cA78FbF26c0B4956C && b != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(a, b);
    }

    receive() external payable {}
}
